public class Account {
    static int totalAccounts = 0;  // shared across all objects
    String owner;

    Account(String owner) {
        this.owner = owner;
        totalAccounts++;  // increment on each creation
    }

    static int getTotal() {
        return totalAccounts;
    }
}

new Account("Alice");
new Account("Bob");
System.out.println(Account.getTotal());  // 2
